using System.Collections.ObjectModel;
using System.ComponentModel;
using System.Runtime.CompilerServices;
using SiamNetworkMonitor.Alerts;
using SiamNetworkMonitor.Models;
using SiamNetworkMonitor.Services;
namespace SiamNetworkMonitor.ViewModels;
public sealed class AdapterRowViewModel{public AdapterRowViewModel(AdapterInfo x){Name=x.Name;Type=x.Type;IPv4=x.IPv4;Gateway=x.Gateway;LinkSpeedText=DisplayFormatter.LinkSpeed(x.LinkSpeedMbps);DownloadText=DisplayFormatter.Rate(x.DownloadKBps);UploadText=DisplayFormatter.Rate(x.UploadKBps);}public string Name{get;}public string Type{get;}public string IPv4{get;}public string Gateway{get;}public string LinkSpeedText{get;}public string DownloadText{get;}public string UploadText{get;}}
public sealed class ProcessRowViewModel:INotifyPropertyChanged
{
 double _down,_up,_sessionDown,_sessionUp,_historyDown,_historyUp;string _path="",_publisher="Unavailable",_description="",_signedText="Unknown";public ProcessRowViewModel(string n,int p){ProcessName=n;ProcessId=p;_description=n;LastActiveUtc=DateTime.UtcNow;}
 public string ProcessName{get;}public int ProcessId{get;private set;}public DateTime LastActiveUtc{get;private set;}public string Path=>_path;public string Publisher=>_publisher;public string Description=>_description;public string SignedText=>_signedText;public bool HasPath=>!string.IsNullOrWhiteSpace(_path);public double DownloadKBps=>_down;public double UploadKBps=>_up;public double SessionDownloadKB=>_sessionDown;public double SessionUploadKB=>_sessionUp;public double HistoryDownloadKB=>_historyDown;public double HistoryUploadKB=>_historyUp;public string DownloadText=>DisplayFormatter.Rate(_down);public string UploadText=>DisplayFormatter.Rate(_up);public string HistoryDownloadText=>DisplayFormatter.Data(_historyDown);public string HistoryUploadText=>DisplayFormatter.Data(_historyUp);public string HistoryTotalText=>DisplayFormatter.Data(_historyDown+_historyUp);
 public void Update(int pid,double d,double u,double elapsed=0,bool active=true){ProcessId=pid;_down=d;_up=u;if(active){LastActiveUtc=DateTime.UtcNow;_sessionDown+=Math.Max(0,d)*elapsed;_sessionUp+=Math.Max(0,u)*elapsed;}Changed();}public void SetHistory(double d,double u){_historyDown=d;_historyUp=u;Changed();}public void SetIdentity(SiamNetworkMonitor.Services.ApplicationIdentity x){_path=x.Path;_publisher=x.Publisher;_description=x.Description;_signedText=x.Signed?"Signed":"Unsigned";Changed();}
 void Changed(){PropertyChanged?.Invoke(this,new(null));}public event PropertyChangedEventHandler? PropertyChanged;
}
public sealed class AlertRowViewModel
{
 public AlertRowViewModel(AlertEvent e){Event=e;}public AlertEvent Event{get;}public Guid Id=>Event.Id;public string TimeText=>Event.TriggeredUtc.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss");public string Severity=>Event.Severity.ToString();public string Rule=>Event.RuleName;public string Application=>string.IsNullOrWhiteSpace(Event.Description)?Event.ProcessName:Event.Description;public string Evidence=>Event.EvidenceSummary;public string Status=>Event.Status.ToString();
}
public sealed class MainViewModel:INotifyPropertyChanged,IDisposable
{
 readonly NetworkMonitor _monitor=new();readonly ProcessTrafficMonitor _processMonitor=new();readonly CsvLogger _logger=new();readonly UsageHistoryService _history=new();readonly ApplicationIdentityService _identity=new();readonly AlertRuleStore _ruleStore=new();readonly AlertEngine _alerts;readonly AlertNotificationService _notifications=new();readonly Dictionary<string,ProcessRowViewModel> _known=new(StringComparer.OrdinalIgnoreCase);readonly System.Windows.Threading.DispatcherTimer _timer;DateTime _previous=DateTime.UtcNow;double _sessionDown,_sessionUp;int _periodDays;bool _isPaused;string _monitoringControlText="Pause";string _periodText="Today",_totalDownloadText="0.00 KB/s",_totalUploadText="0.00 KB/s",_sessionDownloadText="0.00 KB",_sessionUploadText="0.00 KB",_statusText="Starting",_lastUpdatedText="Waiting",_processStatusText="Starting ETW capture...",_alertStatusText="Alerts enabled";
 public MainViewModel(){_alerts=new AlertEngine(_ruleStore.Load());foreach(var e in _alerts.History)Alerts.Add(new(e));_processMonitor.Start();_timer=new(){Interval=TimeSpan.FromSeconds(1)};_timer.Tick+=(_,_)=>Refresh();Refresh();_timer.Start();}
 public ObservableCollection<AdapterRowViewModel> Adapters{get;}=new();public ObservableCollection<ProcessRowViewModel> Processes{get;}=new();public ObservableCollection<AlertRowViewModel> Alerts{get;}=new();public string TotalDownloadText{get=>_totalDownloadText;private set=>Set(ref _totalDownloadText,value);}public string TotalUploadText{get=>_totalUploadText;private set=>Set(ref _totalUploadText,value);}public string SessionDownloadText{get=>_sessionDownloadText;private set=>Set(ref _sessionDownloadText,value);}public string SessionUploadText{get=>_sessionUploadText;private set=>Set(ref _sessionUploadText,value);}public string StatusText{get=>_statusText;private set=>Set(ref _statusText,value);}public string LastUpdatedText{get=>_lastUpdatedText;private set=>Set(ref _lastUpdatedText,value);}public string ProcessStatusText{get=>_processStatusText;private set=>Set(ref _processStatusText,value);}public string AlertStatusText{get=>_alertStatusText;private set=>Set(ref _alertStatusText,value);}public string MonitoringControlText{get=>_monitoringControlText;private set=>Set(ref _monitoringControlText,value);}public bool IsPaused=>_isPaused;public string PeriodText{get=>_periodText;private set=>Set(ref _periodText,value);}public event Action<double,double>? TrafficUpdated;
 public void TogglePause(){_isPaused=!_isPaused;if(_isPaused)_timer.Stop();else{_previous=DateTime.UtcNow;_timer.Start();}MonitoringControlText=_isPaused?"Resume":"Pause";StatusText=_isPaused?"Paused":"Monitoring";PropertyChanged?.Invoke(this,new(nameof(IsPaused)));}
 public void SetPeriod(int d,string l){_periodDays=d;PeriodText=l;ApplyHistory();}public void Export(string p)=>_history.ExportCsv(p,PeriodStart());DateTime PeriodStart()=>_periodDays==0?DateTime.Today:DateTime.Now.AddDays(-_periodDays);void ApplyHistory(){var data=_history.Query(PeriodStart());foreach(var x in data)EnsureRow(x.Key,0).SetHistory(x.Value.Down,x.Value.Up);foreach(var r in _known.Values.Where(x=>!data.ContainsKey(x.ProcessName)))r.SetHistory(0,0);}ProcessRowViewModel EnsureRow(string n,int p){if(_known.TryGetValue(n,out var r))return r;r=new(n,p);_known[n]=r;Processes.Add(r);return r;}
 public List<AlertRule> GetRules()=>_ruleStore.Load();public void ReplaceRules(IEnumerable<AlertRule> rules){var list=rules.ToList();_ruleStore.Save(list);_alerts.ReplaceRules(list);AlertStatusText=$"{list.Count(x=>x.Enabled)} enabled rule(s) • {Alerts.Count} recorded";}
 public void Acknowledge(Guid id){_alerts.Acknowledge(id,null);ReloadAlerts();}public void Resolve(Guid id){_alerts.Resolve(id);ReloadAlerts();}public void ClearAlertHistory(){_alerts.ClearHistory();ReloadAlerts();}void ReloadAlerts(){Alerts.Clear();foreach(var e in _alerts.History)Alerts.Add(new(e));AlertStatusText=$"{Alerts.Count} recorded alert(s)";}
 void Refresh(){var now=DateTime.UtcNow;var elapsed=Math.Max((now-_previous).TotalSeconds,.1);_previous=now;var adapters=_monitor.GetAdapters();var down=adapters.Sum(x=>x.DownloadKBps);var up=adapters.Sum(x=>x.UploadKBps);_sessionDown+=down*elapsed;_sessionUp+=up*elapsed;TotalDownloadText=DisplayFormatter.Rate(down);TotalUploadText=DisplayFormatter.Rate(up);SessionDownloadText=DisplayFormatter.Data(_sessionDown);SessionUploadText=DisplayFormatter.Data(_sessionUp);StatusText=adapters.Count>0?"Monitoring":"No active adapter";LastUpdatedText=$"Updated {DateTime.Now:HH:mm:ss}";Adapters.Clear();foreach(var a in adapters)Adapters.Add(new(a));var samples=_processMonitor.TakeSample(elapsed).GroupBy(x=>x.ProcessName,StringComparer.OrdinalIgnoreCase).Select(g=>new{Name=g.Key,Pid=g.First().ProcessId,Down=g.Sum(x=>x.DownloadKBps),Up=g.Sum(x=>x.UploadKBps)}).ToList();foreach(var r in _known.Values)r.Update(r.ProcessId,0,0,0,false);foreach(var x in samples){var r=EnsureRow(x.Name,x.Pid);r.Update(x.Pid,x.Down,x.Up,elapsed);if(!r.HasPath&&x.Pid>0)r.SetIdentity(_identity.Resolve(x.Pid,x.Name));_history.Add(x.Name,x.Down*elapsed,x.Up*elapsed);}ApplyHistory();var snapshots=_known.Values.Where(r=>r.DownloadKBps>0||r.UploadKBps>0||r.SessionDownloadKB+r.SessionUploadKB>0).Select(r=>new ApplicationTrafficSnapshot{TimestampUtc=now,ProcessId=r.ProcessId,ProcessName=r.ProcessName,Description=r.Description,Publisher=r.Publisher,ExecutablePath=r.Path,IsSigned=r.SignedText=="Signed"?true:r.SignedText=="Unsigned"?false:null,DownloadKBps=r.DownloadKBps,UploadKBps=r.UploadKBps,SessionDownloadKB=r.SessionDownloadKB,SessionUploadKB=r.SessionUploadKB,TodayDownloadKB=r.HistoryDownloadKB,TodayUploadKB=r.HistoryUploadKB}).ToList();var events=_alerts.Evaluate(snapshots,now);foreach(var e in events){Alerts.Insert(0,new(e));_notifications.Show(e);}AlertStatusText=events.Count>0?$"{events.Count} new alert(s) • {Alerts.Count} total":$"Alerts enabled • {Alerts.Count} recorded";ProcessStatusText=$"{samples.Count} active • History: {PeriodText} • 90-day retention";_logger.Log(down,up);TrafficUpdated?.Invoke(down,up);}
 void Set<T>(ref T f,T v,[CallerMemberName]string? n=null){if(EqualityComparer<T>.Default.Equals(f,v))return;f=v;PropertyChanged?.Invoke(this,new(n));}public event PropertyChangedEventHandler? PropertyChanged;public void Dispose(){_timer.Stop();_processMonitor.Dispose();_logger.Dispose();_history.Dispose();_alerts.Dispose();_notifications.Dispose();}
}
